(function () {
  window.anatExtraExams = [
    {name:"CNS Anatomy",questions:[
      {id:"cns-001",difficulty:"Hard",topic:"Neural tube development",subtopic:"Neural plate and neural tube closure",question:"During early CNS development, which sequence correctly describes the formation and closure pattern of the neural tube?",options:{A:"The CNS begins as thickened ectoderm called the neural plate; neural folds fuse first in the cervical region, then cranially and caudally.",B:"The CNS begins from surface ectoderm that invaginates inward; neural tube closure starts at the cranial neuropore and moves caudally.",C:"The neural tube forms by cavitation of mesoderm; fusion begins at the cranial end and progresses only caudally.",D:"The neural tube forms from neural crest cells migrating medially; cranial and caudal neuropores close simultaneously."},correct:"A",explanation:"The CNS originates from thickened ectoderm called the neural plate. Fusion begins in the cervical region and proceeds in both cephalic and caudal directions."},
      {id:"cns-002",difficulty:"Medium",topic:"Neural tube development",subtopic:"Neuropore closure",question:"Which statement correctly identifies the timing of cranial and caudal neuropore closure?",options:{A:"The cranial neuropore closes on day 21 and the caudal neuropore closes on day 25.",B:"The cranial neuropore closes on day 25 and the caudal neuropore closes on day 28.",C:"Both neuropores close during the fourth month of development.",D:"The caudal neuropore closes before the cranial neuropore."},correct:"B",explanation:"The cranial neuropore closes around day 25, while the caudal neuropore closes around day 28."},
      {id:"cns-003",difficulty:"Hard",topic:"Brain vesicles",subtopic:"Primary and secondary brain vesicles",question:"A student is asked to match the primary brain vesicles with their derivatives. Which pairing is correct?",options:{A:"Mesencephalon → telencephalon and diencephalon",B:"Prosencephalon → medulla oblongata and pons",C:"Rhombencephalon → myelencephalon and metencephalon",D:"Metencephalon → thalamus and hypothalamus"},correct:"C",explanation:"The rhombencephalon divides into the myelencephalon, which forms the medulla oblongata, and the metencephalon, which forms the pons and cerebellum."},
      {id:"cns-004",difficulty:"Hard",topic:"Spinal cord development",subtopic:"Mantle and marginal layers",question:"After neural tube closure, neuroepithelial cells differentiate and organize into layers. Which statement is correct?",options:{A:"The mantle layer forms white matter, while the marginal layer forms grey matter.",B:"The roof plate contains motor neurons, while the floor plate contains sensory neurons.",C:"The alar plate gives rise to motor neurons, and the basal plate gives rise to sensory neurons.",D:"The mantle layer forms grey matter; the marginal layer contains nerve fibers and becomes white matter."},correct:"D",explanation:"Neuroblasts form the mantle layer, which becomes grey matter. The marginal layer contains nerve fibers and becomes white matter after myelination."},
      {id:"cns-005",difficulty:"Medium",topic:"Spinal cord development",subtopic:"Basal and alar plates",question:"Which embryological structure is primarily associated with motor neurons in the developing spinal cord?",options:{A:"Basal plate",B:"Alar plate",C:"Roof plate",D:"Neural crest-derived dorsal root ganglion"},correct:"A",explanation:"The basal plate is the ventral thickening of the developing spinal cord and contains motor neurons."},
      {id:"cns-006",difficulty:"Medium",topic:"Spinal cord anatomy",subtopic:"Conus medullaris and cauda equina",question:"In the adult, why can a lumbar puncture be safely performed below the L2 vertebral level?",options:{A:"The spinal cord extends to the sacrum, but the needle tip remains in the epidural space and avoids cord injury.",B:"The spinal cord terminates around L1-L2, while the subarachnoid space continues to approximately S2.",C:"The cauda equina descends freely within the subarachnoid space, so a needle can pass between its roots.",D:"The dural sac ends at L2, so puncture below this level only enters the epidural fat."},correct:"B",explanation:"The adult spinal cord ends around L1-L2 as the conus medullaris, while the subarachnoid space extends to S2, making lower lumbar puncture safer."},
      {id:"cns-007",difficulty:"Medium",topic:"Spinal cord anatomy",subtopic:"Enlargements",question:"Which statement correctly describes the spinal cord enlargements?",options:{A:"The cervical enlargement corresponds to the sacral plexus, and the lumbar enlargement corresponds to the brachial plexus.",B:"Both enlargements reflect increased neuronal density at cervical and lumbar segments but do not relate to limb plexuses.",C:"The cervical enlargement is related to the brachial plexus; the lumbar enlargement is related to the lumbar and sacral plexuses.",D:"The cervical enlargement lies at T11-L1 and the lumbar enlargement lies at C4-T1."},correct:"C",explanation:"The cervical enlargement is located around C4-T1 and corresponds to the brachial plexus. The lumbar enlargement is around T11-L1 and relates to lumbar and sacral plexuses."},
      {id:"cns-008",difficulty:"Hard",topic:"Spinal meninges",subtopic:"Dura, arachnoid, pia",question:"Which description of the spinal meninges is most accurate?",options:{A:"The arachnoid mater is the innermost meningeal layer and gives rise to denticulate ligaments.",B:"The dura mater adheres tightly to the vertebral periosteum, leaving no epidural space in the spine.",C:"The subarachnoid space lies between the dura mater and the vertebral canal wall.",D:"The pia mater covers the spinal cord and thickens between nerve roots to form denticulate ligaments."},correct:"D",explanation:"The pia mater is the innermost meningeal layer and forms denticulate ligaments that help suspend the spinal cord."},
      {id:"cns-009",difficulty:"Medium",topic:"Spinal cord blood supply",subtopic:"Longitudinal arteries",question:"Which vessels form the main longitudinal arterial supply of the spinal cord?",options:{A:"One anterior spinal artery and paired posterior spinal arteries",B:"Paired anterior spinal arteries and one posterior spinal artery",C:"One anterior spinal artery and one posterior spinal artery, supplemented by the basilar artery",D:"Paired posterior spinal arteries only, joined at each segment by radicular branches"},correct:"A",explanation:"The spinal cord is supplied by one anterior spinal artery and two posterior spinal arteries, supplemented by segmental medullary arteries."},
      {id:"cns-010",difficulty:"Hard",topic:"Spinal cord grey matter",subtopic:"Horns and columns",question:"Which spinal cord grey matter region is mainly associated with somatomotor neurons?",options:{A:"Posterior horn",B:"Anterior horn",C:"Central zone",D:"Intermediate column"},correct:"B",explanation:"The anterior horn contains somatomotor neurons and interneurons, while the posterior horn is mainly sensory."},
      {id:"cns-011",difficulty:"Hard",topic:"Spinal cord white matter",subtopic:"Posterior funiculus",question:"A lesion damages the fasciculus gracilis. Which sensory information is most directly affected?",options:{A:"Fine touch, vibration, and proprioception from the upper half of the body",B:"Crude touch and pain from the lower half of the body via the spinothalamic tract",C:"Fine touch, vibration, and proprioception from the lower half of the body",D:"Proprioception and vibration from the upper limb via the cuneate fasciculus"},correct:"C",explanation:"The gracile fasciculus carries dorsal column sensory information from the lower half of the body. The cuneate fasciculus carries similar information from the upper body."},
      {id:"cns-012",difficulty:"Medium",topic:"Medulla oblongata",subtopic:"External anatomy",question:"Which structure on the anterior surface of the medulla contains descending corticospinal and corticobulbar fibers?",options:{A:"Olive",B:"Posterior median sulcus",C:"Inferior cerebellar peduncle",D:"Pyramid"},correct:"D",explanation:"The medullary pyramids are paired anterior swellings that contain descending corticospinal and corticobulbar fibers."},
      {id:"cns-013",difficulty:"Hard",topic:"Medulla oblongata",subtopic:"Cranial nerve exits",question:"Which cranial nerve exits from the ventrolateral sulcus of the medulla?",options:{A:"Hypoglossal nerve (CN XII)",B:"Vagus nerve (CN X)",C:"Glossopharyngeal nerve (CN IX)",D:"Accessory nerve (CN XI)"},correct:"A",explanation:"The hypoglossal nerve emerges from the ventrolateral sulcus of the medulla. CN IX, X, and XI are associated with the posterolateral sulcus."},
      {id:"cns-014",difficulty:"Hard",topic:"Medulla oblongata",subtopic:"Pyramidal decussation",question:"At the level of the pyramidal decussation, what major event occurs?",options:{A:"The corticospinal fibers synapse on interneurons of the anterior horn before decussating.",B:"Most descending motor fibers cross to form the lateral corticospinal tract.",C:"A small proportion of motor fibers cross at the level of the inferior olive.",D:"The medial lemniscus decussates as internal arcuate fibers at this level."},correct:"B",explanation:"At the pyramidal decussation, most corticospinal fibers cross and continue as the lateral corticospinal tract."},
      {id:"cns-015",difficulty:"Hard",topic:"Medulla oblongata",subtopic:"Medial lemniscus formation",question:"Which statement best explains how the medial lemniscus forms in the medulla?",options:{A:"Fibers from the inferior olivary nucleus decussate as external arcuate fibers and form the medial lemniscus.",B:"Second-order spinothalamic neurons decussate in the medulla and continue as the medial lemniscus.",C:"Internal arcuate fibers from the gracile and cuneate nuclei decussate and form the medial lemniscus.",D:"First-order dorsal column fibers cross in the spinal cord and ascend as the medial lemniscus."},correct:"C",explanation:"Second-order fibers from the gracile and cuneate nuclei cross as internal arcuate fibers and form the medial lemniscus."},
      {id:"cns-016",difficulty:"Hard",topic:"Medulla oblongata",subtopic:"Open medulla",question:"Which feature indicates that a medullary section is in the open medulla?",options:{A:"Presence of a closed central canal surrounded by grey matter",B:"Appearance of the inferior olivary nucleus at that level",C:"Visible pyramidal decussation on the anterior surface",D:"Expansion of the central canal into the fourth ventricle"},correct:"D",explanation:"The medulla is considered open when the central canal opens into the fourth ventricle."},
      {id:"cns-017",difficulty:"Hard",topic:"Medulla oblongata",subtopic:"Nuclei",question:"Which nucleus provides motor fibers to cranial nerves IX, X, and XI?",options:{A:"Nucleus ambiguus",B:"Dorsal motor nucleus of vagus",C:"Nucleus solitarius",D:"Inferior salivatory nucleus"},correct:"A",explanation:"The nucleus ambiguus provides motor fibers to cranial nerves IX, X, and XI."},
      {id:"cns-018",difficulty:"Medium",topic:"Pons",subtopic:"External anatomy",question:"Which external feature of the anterior pons is associated with the basilar artery?",options:{A:"Facial colliculus",B:"Basilar groove",C:"Median sulcus of the fourth ventricle",D:"Transverse pontine fibers"},correct:"B",explanation:"The basilar groove is the midline groove on the anterior surface of the pons where the basilar artery lies."},
      {id:"cns-019",difficulty:"Hard",topic:"Pons",subtopic:"Internal anatomy",question:"Which structure is mainly responsible for transmitting pontine information to the cerebellum through the middle cerebellar peduncle?",options:{A:"Abducens nucleus",B:"Inferior olivary nucleus",C:"Pontine nuclei",D:"Superior olivary nucleus"},correct:"C",explanation:"The ventral pons contains pontine nuclei. Their fibers cross and form the middle cerebellar peduncles to reach the cerebellum."},
      {id:"cns-020",difficulty:"Hard",topic:"Pons",subtopic:"Facial colliculus",question:"The facial colliculus is formed mainly because fibers of which cranial nerve loop around which nucleus?",options:{A:"CN VI around the facial motor nucleus",B:"CN IX around the nucleus ambiguus",C:"CN V around the abducens nucleus",D:"CN VII around the abducens nucleus"},correct:"D",explanation:"The facial colliculus is produced by facial nerve fibers looping around the abducens nucleus."},
      {id:"cns-021",difficulty:"Medium",topic:"Rhomboid fossa",subtopic:"Fourth ventricle floor",question:"The rhomboid fossa forms which anatomical surface?",options:{A:"The anterior floor of the fourth ventricle",B:"The posterior wall of the third ventricle",C:"The medial wall of the lateral ventricle",D:"The floor of the cerebral aqueduct"},correct:"A",explanation:"The rhomboid fossa is the diamond-shaped anterior floor of the fourth ventricle."},
      {id:"cns-022",difficulty:"Hard",topic:"Rhomboid fossa",subtopic:"Surface landmarks",question:"Which rhomboid fossa landmark overlies the hypoglossal nucleus?",options:{A:"Facial colliculus",B:"Hypoglossal trigone",C:"Vagal trigone",D:"Vestibular area"},correct:"B",explanation:"The hypoglossal trigone corresponds to the underlying hypoglossal nucleus."},
      {id:"cns-023",difficulty:"Hard",topic:"Rhomboid fossa",subtopic:"Sulcus limitans",question:"What is the functional significance of the sulcus limitans in the rhomboid fossa?",options:{A:"It marks the boundary between open and closed portions of the medulla.",B:"It separates the cerebellar vermis from the hemispheres.",C:"It forms the border between basal and alar plate derivatives.",D:"It connects the median aperture to the subarachnoid space."},correct:"C",explanation:"The sulcus limitans separates medial motor/basal plate derivatives from lateral sensory/alar plate derivatives."},
      {id:"cns-024",difficulty:"Medium",topic:"Midbrain",subtopic:"External anatomy",question:"Which midbrain region is located posterior to the cerebral aqueduct and contains the colliculi?",options:{A:"Crus cerebri",B:"Tegmentum",C:"Interpeduncular fossa",D:"Tectum"},correct:"D",explanation:"The tectum is posterior to the cerebral aqueduct and contains the superior and inferior colliculi."},
      {id:"cns-025",difficulty:"Hard",topic:"Midbrain",subtopic:"Cerebral peduncles",question:"Which structure divides the cerebral peduncle into the anterior crus cerebri and posterior tegmentum?",options:{A:"Substantia nigra",B:"Red nucleus",C:"Cerebral aqueduct",D:"Superior colliculus"},correct:"A",explanation:"The substantia nigra separates the anterior crus cerebri from the posterior tegmentum."},
      {id:"cns-026",difficulty:"Hard",topic:"Midbrain",subtopic:"Inferior colliculus level",question:"At the level of the inferior colliculus, which cranial nerve nucleus is found in the periaqueductal grey?",options:{A:"Oculomotor nucleus",B:"Trochlear nucleus",C:"Abducens nucleus",D:"Hypoglossal nucleus"},correct:"B",explanation:"At the inferior colliculus level, the trochlear nucleus is located in the periaqueductal grey."},
      {id:"cns-027",difficulty:"Hard",topic:"Midbrain",subtopic:"Superior colliculus level",question:"At the level of the superior colliculus, which structure replaces the trochlear nucleus?",options:{A:"Facial nucleus",B:"Nucleus ambiguus",C:"Oculomotor nucleus",D:"Dorsal motor nucleus of vagus"},correct:"C",explanation:"At the superior colliculus level, the oculomotor nucleus is present instead of the trochlear nucleus."},
      {id:"cns-028",difficulty:"Hard",topic:"Midbrain",subtopic:"Lemnisci",question:"Which lemniscus does not reach the superior colliculus level according to the notes?",options:{A:"Trigeminal lemniscus",B:"Medial lemniscus",C:"Spinal lemniscus",D:"Lateral lemniscus"},correct:"D",explanation:"At the superior colliculus level, the medial, spinal, and trigeminal lemnisci are present, but the lateral lemniscus does not reach this level."},
      {id:"cns-029",difficulty:"Hard",topic:"Reticular formation",subtopic:"Columns",question:"Which reticular formation column contains raphe nuclei and is strongly associated with serotonin release?",options:{A:"Median column",B:"Lateral parvocellular zone",C:"Medial magnocellular zone",D:"Ventral gigantocellular zone"},correct:"A",explanation:"The median column contains the raphe nuclei, which are involved in serotonin release, arousal, mood, and pain modulation."},
      {id:"cns-030",difficulty:"Hard",topic:"Reticular formation",subtopic:"Ascending reticular activation system",question:"Which function is most closely associated with the ascending reticular activation system?",options:{A:"Direct voluntary control of distal limb muscles via corticospinal projections",B:"Regulation of consciousness, arousal, and integration of sensory-autonomic information",C:"Relay of sensory information exclusively to the thalamus via the medial lemniscus",D:"Modulation of pain via descending serotonergic raphe projections only"},correct:"B",explanation:"The ascending reticular activation system is important for consciousness, arousal, and integration of sensory/autonomic information."},
      {id:"cns-031",difficulty:"Medium",topic:"Cerebellum",subtopic:"Embryological origin",question:"The cerebellum develops from which secondary brain vesicle?",options:{A:"Telencephalon",B:"Diencephalon",C:"Metencephalon",D:"Myelencephalon"},correct:"C",explanation:"The metencephalon gives rise to the pons and cerebellum."},
      {id:"cns-032",difficulty:"Medium",topic:"Cerebellum",subtopic:"Cortex layers",question:"Which is the correct order of cerebellar cortex layers from superficial to deep?",options:{A:"Molecular layer → Granular layer → Purkinje layer",B:"Granular layer → Purkinje layer → Molecular layer",C:"Purkinje layer → Granular layer → Molecular layer",D:"Molecular layer → Purkinje layer → Granular layer"},correct:"D",explanation:"The cerebellar cortex consists of superficial molecular layer, middle Purkinje cell layer, and deep granular layer."},
      {id:"cns-033",difficulty:"Hard",topic:"Cerebellum",subtopic:"Functional divisions",question:"Which cerebellar functional division is mainly involved in balance and ocular reflexes?",options:{A:"Vestibulocerebellum",B:"Cerebrocerebellum",C:"Spinocerebellum",D:"Neocerebellum"},correct:"A",explanation:"The vestibulocerebellum corresponds functionally to the flocculonodular lobe and is involved in balance and ocular reflexes."},
      {id:"cns-034",difficulty:"Hard",topic:"Cerebellum",subtopic:"Deep nuclei",question:"Which deep cerebellar nucleus is most lateral and receives afferents from the pontocerebellar system?",options:{A:"Fastigial nucleus",B:"Dentate nucleus",C:"Interposed nucleus",D:"Emboliform nucleus"},correct:"B",explanation:"The dentate nucleus is the large lateral cerebellar nucleus and receives afferents from the pontocerebellar system."},
      {id:"cns-035",difficulty:"Hard",topic:"Cerebellar connections",subtopic:"Inferior cerebellar peduncle",question:"Which tract originates in the inferior olivary complex and terminates contralaterally as climbing fibers on Purkinje cells?",options:{A:"Posterior spinocerebellar tract",B:"Cuneocerebellar tract",C:"Olivocerebellar tract",D:"Pontocerebellar tract"},correct:"C",explanation:"The olivocerebellar tract arises from the inferior olivary complex and terminates contralaterally as climbing fibers on Purkinje cells."},
      {id:"cns-036",difficulty:"Medium",topic:"Cerebellar connections",subtopic:"Pontocerebellar tract",question:"The pontocerebellar tract reaches the cerebellum mainly through which cerebellar peduncle?",options:{A:"No cerebellar peduncle; it enters through the thalamus",B:"Inferior cerebellar peduncle",C:"Superior cerebellar peduncle",D:"Middle cerebellar peduncle"},correct:"D",explanation:"The pontocerebellar tract travels through the middle cerebellar peduncle and terminates as mossy fibers in the contralateral cerebellar hemisphere."},
      {id:"cns-037",difficulty:"Hard",topic:"Cerebellar cortex",subtopic:"Intrinsic neurons",question:"Which cerebellar cortical neuron is described as the only excitatory neuron in the cerebellar cortex?",options:{A:"Granule cell",B:"Purkinje cell",C:"Stellate cell",D:"Golgi cell"},correct:"A",explanation:"Granule cells are the only excitatory neurons in the cerebellar cortex and use glutamate."},
      {id:"cns-038",difficulty:"Hard",topic:"Cerebellar cortex",subtopic:"Purkinje cells",question:"Which statement correctly describes Purkinje cells?",options:{A:"They are excitatory neurons that project from the molecular layer to the granular layer.",B:"They are inhibitory neurons whose axons project to cerebellar nuclei.",C:"They are excitatory interneurons that synapse on basket and stellate cells.",D:"They provide the sole output of the cerebellar cortex using glutamate."},correct:"B",explanation:"Purkinje cells are inhibitory neurons; their axons run to deep cerebellar nuclei."},
      {id:"cns-039",difficulty:"Hard",topic:"Diencephalon",subtopic:"Borders",question:"Which structures form part of the floor of the diencephalon?",options:{A:"Tela choroidea and fornix",B:"Internal capsule and lentiform nucleus",C:"Optic chiasm, infundibulum, and mammillary bodies",D:"Pineal gland and posterior commissure"},correct:"C",explanation:"The floor of the diencephalon is formed by the optic chiasm, optic tract region, infundibulum, and mammillary bodies."},
      {id:"cns-040",difficulty:"Medium",topic:"Diencephalon",subtopic:"Major subdivisions",question:"Which list contains the four major subdivisions of the diencephalon?",options:{A:"Tectum, tegmentum, crus cerebri, substantia nigra",B:"Thalamus, pons, medulla, cerebellum",C:"Caudate nucleus, putamen, globus pallidus, claustrum",D:"Epithalamus, thalamus, subthalamus, hypothalamus"},correct:"D",explanation:"The diencephalon is divided into epithalamus, thalamus, subthalamus, and hypothalamus."},
      {id:"cns-041",difficulty:"Medium",topic:"Epithalamus",subtopic:"Pineal gland",question:"Which statement about the pineal gland is correct?",options:{A:"It secretes melatonin in response to darkness and is involved in circadian rhythm.",B:"It secretes melatonin in response to bright light and is involved in sleep onset.",C:"It is a vascular structure that produces CSF within the third ventricle.",D:"It receives direct projections from the suprachiasmatic nucleus via the thalamus."},correct:"A",explanation:"The pineal gland contains pinealocytes that secrete melatonin in response to darkness and helps regulate circadian rhythm."},
      {id:"cns-042",difficulty:"Hard",topic:"Thalamus",subtopic:"External features",question:"Which thalamic external feature contains fibers from the amygdaloid body to the hypothalamus and runs with the superior thalamostriate vein?",options:{A:"Stria medullaris thalami",B:"Stria terminalis",C:"Tenia thalami",D:"Lamina affixa"},correct:"B",explanation:"The stria terminalis carries fibers from the amygdala to hypothalamic/septal regions and runs with the superior thalamostriate vein."},
      {id:"cns-043",difficulty:"Hard",topic:"Thalamus",subtopic:"Functional nuclei",question:"Which thalamic nucleus is involved in the auditory pathway?",options:{A:"Lateral geniculate body",B:"Pulvinar",C:"Medial geniculate body",D:"Ventral posteromedial nucleus"},correct:"C",explanation:"The medial geniculate body is the thalamic relay nucleus for auditory information."},
      {id:"cns-044",difficulty:"Hard",topic:"Thalamus",subtopic:"Functional nuclei",question:"Which thalamic nucleus receives sensory input from the dorsal column-medial lemniscal pathway and anterolateral system of the body?",options:{A:"Medial geniculate body",B:"Ventral posteromedial nucleus",C:"Ventral lateral nucleus",D:"Ventral posterolateral nucleus"},correct:"D",explanation:"The ventral posterolateral nucleus receives somatosensory information from the body, including DCML and spinothalamic inputs."},
      {id:"cns-045",difficulty:"Hard",topic:"Thalamus",subtopic:"Papez circuit",question:"Which thalamic nucleus is classically involved in the Papez circuit and episodic memory?",options:{A:"Anterior thalamic nucleus",B:"Pulvinar nucleus",C:"Mediodorsal nucleus",D:"Centromedian nucleus"},correct:"A",explanation:"The anterior thalamic nuclei participate in the Papez circuit, which is important for memory and emotional processing."},
      {id:"cns-046",difficulty:"Hard",topic:"Hypothalamus",subtopic:"Zones and nuclei",question:"Which group correctly belongs to the tuberal zone of the hypothalamus?",options:{A:"Supraoptic, paraventricular, suprachiasmatic",B:"Arcuate nucleus, ventromedial nucleus, dorsomedial nucleus",C:"Mammillary nuclei and posterior hypothalamic nucleus",D:"Lateral hypothalamic nucleus and anterior hypothalamic nucleus"},correct:"B",explanation:"The tuberal zone includes the arcuate, ventromedial, and dorsomedial nuclei."},
      {id:"cns-047",difficulty:"Hard",topic:"Hypothalamus",subtopic:"Hunger and satiety",question:"Which hypothalamic nucleus is described as stimulating hunger through orexin release?",options:{A:"Ventromedial nucleus",B:"Dorsomedial nucleus",C:"Lateral hypothalamic nucleus",D:"Posterior hypothalamic nucleus"},correct:"C",explanation:"The lateral hypothalamic nucleus is associated with hunger and releases orexins."},
      {id:"cns-048",difficulty:"Hard",topic:"Hypothalamus",subtopic:"Neurohypophyseal regulation",question:"Which nuclei give rise to the hypothalamohypophyseal tract that projects to the posterior pituitary?",options:{A:"Arcuate and ventromedial hypothalamic nuclei",B:"Anterior thalamic and dorsomedial thalamic nuclei",C:"Lateral and posterior hypothalamic nuclei",D:"Supraoptic and paraventricular nuclei"},correct:"D",explanation:"The hypothalamohypophyseal tract originates from neurosecretory cells in the supraoptic and paraventricular nuclei."},
      {id:"cns-049",difficulty:"Hard",topic:"Hypothalamohypophyseal system",subtopic:"Portal circulation",question:"Which structure forms the primary capillary plexus involved in hypothalamic regulation of the anterior pituitary?",options:{A:"Superior hypophyseal artery",B:"Inferior hypophyseal artery",C:"Middle hypophyseal artery",D:"Posterior communicating artery"},correct:"A",explanation:"The superior hypophyseal artery forms the primary capillary plexus around the hypothalamus, which connects to the anterior pituitary through portal vessels."},
      {id:"cns-050",difficulty:"Hard",topic:"Basal ganglia",subtopic:"Components",question:"Which pair forms the striatum?",options:{A:"Globus pallidus internus and externus",B:"Caudate nucleus and putamen",C:"Subthalamic nucleus and globus pallidus",D:"Caudate nucleus and globus pallidus"},correct:"B",explanation:"The striatum is formed by the caudate nucleus and putamen."},
      {id:"cns-051",difficulty:"Hard",topic:"Basal ganglia",subtopic:"Input and output nuclei",question:"Which basal ganglia components are output nuclei?",options:{A:"Caudate nucleus and putamen",B:"External globus pallidus and subthalamic nucleus",C:"Internal globus pallidus and pars reticulata of substantia nigra",D:"Pars compacta of substantia nigra and internal globus pallidus"},correct:"C",explanation:"The main output nuclei are the internal globus pallidus and pars reticulata of the substantia nigra."},
      {id:"cns-052",difficulty:"Hard",topic:"Basal ganglia",subtopic:"Direct pathway",question:"What is the overall functional effect of the direct basal ganglia pathway?",options:{A:"It activates the subthalamic nucleus, increasing inhibitory output to the thalamus.",B:"It blocks striatal projections to the external globus pallidus.",C:"It reduces dopamine release from the substantia nigra pars compacta.",D:"It facilitates movement by reducing inhibitory output to the thalamus."},correct:"D",explanation:"The direct pathway facilitates movement by inhibiting the output nuclei, thereby disinhibiting thalamic excitation of motor cortex."},
      {id:"cns-053",difficulty:"Hard",topic:"Basal ganglia",subtopic:"Indirect pathway",question:"What is the overall functional effect of the indirect basal ganglia pathway?",options:{A:"It inhibits movement by increasing inhibitory output to the thalamus.",B:"It disinhibits the subthalamic nucleus, reducing striatal output.",C:"It activates the external globus pallidus, which then excites the thalamus.",D:"It bypasses the globus pallidus and acts directly on the motor cortex."},correct:"A",explanation:"The indirect pathway increases inhibitory influence on the thalamus, thereby reducing motor cortical activation and suppressing movement."},
      {id:"cns-054",difficulty:"Hard",topic:"Basal ganglia",subtopic:"Parkinsonism",question:"Parkinsonism is primarily associated with degeneration of which neurons?",options:{A:"Serotonergic neurons of the raphe nuclei",B:"Dopaminergic neurons of the substantia nigra",C:"GABAergic neurons of the striatum",D:"Cholinergic neurons of the basal nucleus of Meynert"},correct:"B",explanation:"Parkinsonism involves degeneration of dopaminergic neurons in the substantia nigra, impairing basal ganglia modulation of movement."},
      {id:"cns-055",difficulty:"Hard",topic:"Extrapyramidal tracts",subtopic:"Vestibulospinal tract",question:"Which statement best describes the vestibulospinal tracts?",options:{A:"They arise from the red nucleus and influence limb flexor tone.",B:"They arise from the superior colliculus and coordinate head movement to visual stimuli.",C:"They arise from vestibular nuclei and help control balance and posture through antigravity muscles.",D:"They arise from the motor cortex and descend through the medullary pyramids."},correct:"C",explanation:"The vestibulospinal tracts arise from vestibular nuclei and influence balance and posture by acting on antigravity muscles."},
      {id:"cns-056",difficulty:"Medium",topic:"Extrapyramidal tracts",subtopic:"Tectospinal tract",question:"The tectospinal tract begins mainly from which structure?",options:{A:"Inferior colliculus",B:"Red nucleus",C:"Pretectal area",D:"Superior colliculus"},correct:"D",explanation:"The tectospinal tract begins in the superior colliculus and coordinates head movements in response to visual stimuli."},
      {id:"cns-057",difficulty:"Hard",topic:"Cerebral cortex",subtopic:"Neocortex layers",question:"Which neocortical layer contains large pyramidal neurons, including Betz cells, and is dominant in motor cortex efferentation?",options:{A:"Layer V, internal pyramidal layer",B:"Layer VI, multiform layer",C:"Layer IV, internal granular layer",D:"Layer III, external pyramidal layer"},correct:"A",explanation:"Layer V contains large pyramidal neurons, including Betz cells, and is especially prominent in motor areas."},
      {id:"cns-058",difficulty:"Medium",topic:"Cerebral cortex",subtopic:"Primary motor cortex",question:"Where is the primary motor cortex located?",options:{A:"Postcentral gyrus",B:"Precentral gyrus",C:"Inferior frontal gyrus",D:"Superior frontal gyrus"},correct:"B",explanation:"The primary motor cortex is located in the precentral gyrus and corresponds to Brodmann area 4."},
      {id:"cns-059",difficulty:"Medium",topic:"Cerebral cortex",subtopic:"Primary somatosensory cortex",question:"The primary somatosensory cortex receives major thalamic input from which nuclei?",options:{A:"Anterior thalamic and mediodorsal nuclei",B:"Medial and lateral geniculate bodies",C:"Ventral posterolateral and ventral posteromedial nuclei",D:"Pulvinar and centromedian nuclei"},correct:"C",explanation:"The primary somatosensory cortex receives body and facial sensory information from VPL and VPM nuclei."},
      {id:"cns-060",difficulty:"Medium",topic:"Cerebral cortex",subtopic:"Visual cortex",question:"The primary visual cortex corresponds to which Brodmann area and location?",options:{A:"BA 41/42, transverse temporal gyri",B:"BA 18, cuneus of the occipital lobe",C:"BA 7, superior parietal lobule",D:"BA 17, calcarine sulcus"},correct:"D",explanation:"The primary visual cortex is Brodmann area 17 and is located around the calcarine sulcus."},
      {id:"cns-061",difficulty:"Hard",topic:"Cerebral cortex",subtopic:"Speech areas",question:"Which statement correctly describes Broca's area?",options:{A:"It is located in the inferior frontal gyrus and is important for speech production.",B:"It is located in the superior temporal gyrus and is important for speech production.",C:"It is located in the postcentral gyrus and mediates integration of speech with somatosensory input.",D:"It is located in the angular gyrus and governs reading aloud."},correct:"A",explanation:"Broca's motor speech area is located in the inferior frontal gyrus and is important for speech production."},
      {id:"cns-062",difficulty:"Medium",topic:"Cerebral cortex",subtopic:"Auditory cortex",question:"The primary auditory cortex is located mainly in which structure?",options:{A:"Precentral gyrus",B:"Transverse temporal gyri of Heschl",C:"Planum temporale",D:"Superior temporal sulcus"},correct:"B",explanation:"The primary auditory cortex, Brodmann areas 41 and 42, is located in the transverse temporal gyri of Heschl."},
      {id:"cns-063",difficulty:"Medium",topic:"Cerebral cortex",subtopic:"Gustatory area",question:"The gustatory cortex is mainly located in which region?",options:{A:"Inferior frontal gyrus and adjacent premotor cortex",B:"Posterior insula only",C:"Opercular part of the postcentral gyrus and adjacent insular cortex",D:"Anterior cingulate gyrus"},correct:"C",explanation:"The gustatory area, Brodmann area 43, is located in the opercular part of the postcentral gyrus and adjacent insular cortex."},
      {id:"cns-064",difficulty:"Hard",topic:"Cerebral white matter",subtopic:"Internal capsule",question:"Which statement about the internal capsule is correct?",options:{A:"It lies between the caudate nucleus and the claustrum and carries only association fibers.",B:"It lies between the lentiform nucleus and claustrum and contains only association fibers.",C:"It lies medial to the thalamus and contains the corticospinal fibers running to the cerebellum.",D:"It lies lateral to the thalamus and caudate nucleus and medial to the globus pallidus."},correct:"D",explanation:"The internal capsule lies lateral to the thalamus and caudate nucleus and medial to the globus pallidus."},
      {id:"cns-065",difficulty:"Hard",topic:"Cerebral white matter",subtopic:"Internal capsule parts",question:"Which tract is classically located in the genu of the internal capsule?",options:{A:"Corticonuclear tract",B:"Anterior thalamic radiation",C:"Corticospinal fibers to the lower limb",D:"Acoustic radiation"},correct:"A",explanation:"The genu of the internal capsule contains corticonuclear fibers."},
      {id:"cns-066",difficulty:"Hard",topic:"Cerebral white matter",subtopic:"Association fibers",question:"Which association fiber tract connects Broca's area with Wernicke's area?",options:{A:"Cingulum",B:"Arcuate fasciculus",C:"Superior longitudinal fasciculus",D:"Uncinate fasciculus"},correct:"B",explanation:"The arcuate fasciculus connects Broca's and Wernicke's areas and is crucial for communication between motor and sensory speech regions."},
      {id:"cns-067",difficulty:"Medium",topic:"Cerebral white matter",subtopic:"Commissural fibers",question:"Which structure is the major commissural fiber bundle interconnecting neocortical gyri of both cerebral hemispheres?",options:{A:"Anterior commissure",B:"Cingulum",C:"Corpus callosum",D:"Corona radiata"},correct:"C",explanation:"The corpus callosum is the major commissural bundle connecting the neocortical areas of both hemispheres."},
      {id:"cns-068",difficulty:"Hard",topic:"Ventricular system",subtopic:"CSF flow",question:"Which sequence correctly describes normal CSF flow from the lateral ventricles?",options:{A:"Fourth ventricle → cerebral aqueduct → third ventricle → lateral ventricles → arachnoid granulations",B:"Lateral ventricles → cerebral aqueduct → third ventricle → fourth ventricle → interventricular foramina",C:"Third ventricle → interventricular foramina → lateral ventricles → central canal → subarachnoid space",D:"Lateral ventricles → foramina of Monro → third ventricle → cerebral aqueduct → fourth ventricle → subarachnoid space"},correct:"D",explanation:"CSF flows from lateral ventricles through the foramina of Monro to the third ventricle, then through the cerebral aqueduct to the fourth ventricle, then into the subarachnoid space or central canal."},
      {id:"cns-069",difficulty:"Hard",topic:"CSF",subtopic:"Production and absorption",question:"Where is CSF mainly produced and where is it reabsorbed?",options:{A:"Produced by choroid plexus/ventricular ependyma and reabsorbed through arachnoid granulations",B:"Produced by arachnoid granulations and reabsorbed by the choroid plexus",C:"Produced by the ependymal cells lining the central canal and reabsorbed by periventricular capillaries",D:"Produced mainly in the subarachnoid cisterns and reabsorbed by lymphatics around the cranial nerves"},correct:"A",explanation:"CSF is produced mainly by secretion from the choroid plexus and ventricular ependyma, and is reabsorbed through arachnoid granulations into dural venous sinuses."},
      {id:"cns-070",difficulty:"Hard",topic:"Hydrocephalus",subtopic:"Types",question:"Which statement best describes communicating hydrocephalus?",options:{A:"It results from overproduction of CSF by the choroid plexus alone.",B:"CSF reaches the subarachnoid space, but pressure is increased because absorption or balance is impaired.",C:"It occurs when the lateral ventricles are disconnected from the third ventricle.",D:"It results specifically from obstruction of the cerebral aqueduct."},correct:"B",explanation:"In communicating hydrocephalus, there is no block preventing CSF from reaching the subarachnoid space, but CSF pressure increases, often due to impaired absorption."},
      {id:"cns-071",difficulty:"Hard",topic:"Brain blood supply",subtopic:"Circle of Willis",question:"Which arteries form the main paired cerebral arteries of the Circle of Willis?",options:{A:"Ophthalmic, anterior choroidal, and posterior communicating arteries",B:"Anterior cerebral, posterior cerebral, and basilar arteries",C:"Anterior cerebral, internal carotid, and posterior cerebral arteries",D:"Middle cerebral, anterior cerebral, and anterior communicating arteries"},correct:"C",explanation:"The circle includes paired anterior cerebral arteries, internal carotid arteries, and posterior cerebral arteries, connected by anterior and posterior communicating arteries."},
      {id:"cns-072",difficulty:"Medium",topic:"Brain blood supply",subtopic:"Internal carotid branches",question:"Which artery is a terminal branch of the internal carotid artery?",options:{A:"Anterior choroidal artery",B:"Posterior communicating artery",C:"Anterior cerebral artery",D:"Middle cerebral artery"},correct:"D",explanation:"The middle cerebral artery is one of the terminal branches of the internal carotid artery."},
      {id:"cns-073",difficulty:"Hard",topic:"Brain blood supply",subtopic:"Vertebral artery branches",question:"Which branch of the vertebral artery supplies the cerebellum according to the notes?",options:{A:"Posterior inferior cerebellar artery",B:"Anterior inferior cerebellar artery",C:"Superior cerebellar artery",D:"Posterior spinal artery"},correct:"A",explanation:"The posterior inferior cerebellar artery arises from the vertebral artery and supplies the cerebellum."},
      {id:"cns-074",difficulty:"Hard",topic:"Brain blood supply",subtopic:"Cerebral artery territories",question:"A patient has contralateral weakness and sensory loss mainly affecting the face and arm, with aphasia if the dominant hemisphere is involved. Which artery is most likely occluded?",options:{A:"Anterior cerebral artery",B:"Middle cerebral artery",C:"Posterior cerebral artery",D:"Anterior choroidal artery"},correct:"B",explanation:"Middle cerebral artery occlusion typically affects the lateral cerebral hemisphere, causing contralateral face/arm weakness and sensory loss, and aphasia if the dominant hemisphere is affected."},
      {id:"cns-075",difficulty:"Hard",topic:"Blood-brain barrier",subtopic:"Structure",question:"Which components contribute directly to the structure of the blood-brain barrier?",options:{A:"Capillary endothelial cells with fenestrations and a thick basal lamina",B:"Arachnoid granulations and the outer dura mater",C:"Capillary endothelial cells with tight junctions, astrocytic end-feet, and pericytes",D:"Choroid plexus epithelium and ependymal lining cells"},correct:"C",explanation:"The BBB is formed by specialized endothelial cells with tight junctions, supported by basement membrane, astrocytic end-feet, and pericytes."},
      {id:"cns-076",difficulty:"Hard",topic:"DCML pathway",subtopic:"First-order neurons",question:"Where are the first-order neurons of the dorsal column-medial lemniscal pathway located?",options:{A:"Ventral horn of spinal cord",B:"Gracile and cuneate nuclei in the medulla",C:"Ventral posterolateral nucleus of thalamus",D:"Dorsal root ganglia"},correct:"D",explanation:"First-order DCML neurons are pseudounipolar neurons located in dorsal root ganglia."},
      {id:"cns-077",difficulty:"Hard",topic:"DCML pathway",subtopic:"Fasciculi",question:"Which statement correctly distinguishes gracile and cuneate fasciculi?",options:{A:"Gracile fasciculus carries lower body input below T6; cuneate fasciculus carries upper body input from T6 and above.",B:"Gracile fasciculus carries pain only; cuneate fasciculus carries vibration only.",C:"Cuneate fasciculus is medial; gracile fasciculus is lateral in the posterior funiculus.",D:"Both fasciculi carry fine touch but not proprioception."},correct:"A",explanation:"Lower body information travels in the medial gracile fasciculus, while upper body information travels in the lateral cuneate fasciculus."},
      {id:"cns-078",difficulty:"Hard",topic:"DCML pathway",subtopic:"Lesions",question:"A lesion below the decussation of the DCML pathway will produce which sensory pattern?",options:{A:"Contralateral loss of fine touch, vibration, and proprioception below the lesion",B:"Ipsilateral loss of fine touch, vibration, and proprioception below the lesion",C:"Bilateral loss of fine touch, vibration, and proprioception below the lesion",D:"Contralateral loss of pain and temperature below the lesion only"},correct:"B",explanation:"Because DCML fibers decussate in the medulla, lesions below the decussation cause ipsilateral loss of fine touch, vibration, and proprioception."},
      {id:"cns-079",difficulty:"Hard",topic:"Anterolateral system",subtopic:"Spinothalamic tracts",question:"Which tract carries pain and temperature information?",options:{A:"Anterior spinothalamic tract",B:"Spinoreticular tract",C:"Lateral spinothalamic tract",D:"Spinotectal tract"},correct:"C",explanation:"The lateral spinothalamic tract carries pain and temperature sensation."},
      {id:"cns-080",difficulty:"Hard",topic:"Anterolateral system",subtopic:"Spinoreticular tract",question:"Which tract transmits slow pain and contributes to regulation of arousal through the reticular activation system?",options:{A:"Spinotectal tract",B:"Lateral spinothalamic tract",C:"Anterior spinothalamic tract",D:"Spinoreticular tract"},correct:"D",explanation:"The spinoreticular tract transmits slow pain to the reticular formation and contributes to consciousness/arousal regulation."},
      {id:"cns-081",difficulty:"Hard",topic:"Anterolateral system",subtopic:"Spinotectal tract",question:"The spinotectal tract terminates mainly in which midbrain structure?",options:{A:"Superior colliculus",B:"Inferior colliculus",C:"Pretectal area",D:"Red nucleus"},correct:"A",explanation:"The spinotectal tract terminates in the superior colliculus and helps integrate tactile/proprioceptive information with visual reflexes."},
      {id:"cns-082",difficulty:"Hard",topic:"Pyramidal system",subtopic:"Corticospinal tract",question:"Which sequence correctly describes the corticospinal tract after it leaves the cerebral cortex?",options:{A:"Cortex → internal capsule → cerebral aqueduct → pontine nuclei → spinal cord",B:"Cortex → internal capsule → crus cerebri → pons → medulla → spinal cord",C:"Cortex → corona radiata → thalamus → internal capsule → spinal cord",D:"Cortex → corona radiata → corpus callosum → anterior commissure → spinal cord"},correct:"B",explanation:"Corticospinal fibers descend through the internal capsule, crus cerebri, pons, medulla, and then into the spinal cord."},
      {id:"cns-083",difficulty:"Hard",topic:"Pyramidal system",subtopic:"Lateral corticospinal tract",question:"Which statement about the lateral corticospinal tract is correct?",options:{A:"Its fibers remain ipsilateral throughout, forming the anterior corticospinal tract.",B:"Its fibers decussate at the level of each spinal cord segment before synapsing.",C:"Its fibers decussate in the caudal medulla and descend in the spinal cord to influence lower motor neurons.",D:"It originates from neurons in the premotor cortex only."},correct:"C",explanation:"Most corticospinal fibers cross in the pyramidal decussation and continue as the lateral corticospinal tract."},
      {id:"cns-084",difficulty:"Hard",topic:"Pyramidal system",subtopic:"Corticobulbar tract",question:"The corticobulbar tract primarily terminates on which structures?",options:{A:"Posterior horn sensory nuclei",B:"Dorsal root ganglia",C:"Choroid plexus epithelial cells",D:"Motor nuclei of cranial nerves"},correct:"D",explanation:"Corticobulbar fibers terminate on motor nuclei of cranial nerves to control muscles of the face and neck."},
      {id:"cns-085",difficulty:"Medium",topic:"Auditory pathway",subtopic:"First-order neurons",question:"Where are the first-order neurons of the auditory pathway located?",options:{A:"Spiral ganglion",B:"Geniculate ganglion",C:"Dorsal root ganglion",D:"Ventral posteromedial nucleus"},correct:"A",explanation:"First-order auditory neurons are bipolar neurons located in the spiral ganglion."},
      {id:"cns-086",difficulty:"Hard",topic:"Auditory pathway",subtopic:"Major relays",question:"Which relay sequence is most accurate for conscious auditory perception?",options:{A:"Retina → optic nerve → optic chiasm → lateral geniculate body → optic radiation → calcarine cortex",B:"Spiral ganglion → cochlear nuclei → inferior colliculus → medial geniculate body → primary auditory cortex",C:"Olfactory receptor cells → olfactory nerve → olfactory bulb → olfactory tract → piriform cortex",D:"Taste receptors → chorda tympani → solitary nucleus → VPM thalamic nucleus → insular cortex"},correct:"B",explanation:"The auditory pathway relays from spiral ganglion to cochlear nuclei, inferior colliculus, medial geniculate body, and then primary auditory cortex."},
      {id:"cns-087",difficulty:"Hard",topic:"Visual pathway",subtopic:"Retinal neurons",question:"Which sequence correctly identifies the first three neuronal levels of the visual pathway?",options:{A:"Ganglion cells → bipolar cells → rods and cones",B:"Bipolar cells → rods and cones → lateral geniculate body",C:"Rods/cones → bipolar neurons → retinal ganglion cells",D:"Lateral geniculate body → optic nerve → rods/cones"},correct:"C",explanation:"The visual pathway begins with photoreceptors, then bipolar neurons, then retinal ganglion cells whose axons form the optic nerve."},
      {id:"cns-088",difficulty:"Hard",topic:"Visual pathway",subtopic:"Optic radiation",question:"The axons of neurons in which structure form the optic radiation?",options:{A:"Medial geniculate body",B:"Superior olivary nucleus",C:"Spiral ganglion",D:"Lateral geniculate body"},correct:"D",explanation:"Fourth-order visual neurons are in the lateral geniculate body, and their axons form the optic radiation to the primary visual cortex."},
      {id:"cns-089",difficulty:"Hard",topic:"Olfactory pathway",subtopic:"Olfactory cortex",question:"Which set of structures is included in the olfactory cortex according to the notes?",options:{A:"Piriform cortex, amygdala, and entorhinal cortex",B:"Precentral gyrus, postcentral gyrus, and calcarine cortex",C:"Lateral geniculate body, medial geniculate body, and pulvinar",D:"Dentate nucleus, fastigial nucleus, and emboliform nucleus"},correct:"A",explanation:"The olfactory cortex includes the piriform cortex, amygdala, and entorhinal cortex."},
      {id:"cns-090",difficulty:"Hard",topic:"Gustatory pathway",subtopic:"Taste relays",question:"Taste fibers from the solitary nucleus ascend mainly to which thalamic nucleus?",options:{A:"Ventral posterolateral nucleus",B:"Ventral posteromedial nucleus",C:"Anterior thalamic nucleus",D:"Lateral geniculate body"},correct:"B",explanation:"Gustatory fibers from the solitary nucleus ascend to the ventral posteromedial nucleus of the thalamus before reaching the gustatory cortex."},
      {id:"cns-091",difficulty:"Medium",topic:"Limbic system",subtopic:"Main functions",question:"Which list best summarizes the main functions of the limbic system?",options:{A:"Voluntary movement only",B:"CSF production and reabsorption only",C:"Olfaction, memory, emotional responses, and behavior",D:"Visual acuity and pupillary constriction only"},correct:"C",explanation:"The limbic system is involved in olfaction, memory, emotional responses, and behavior."},
      {id:"cns-092",difficulty:"Hard",topic:"Limbic system",subtopic:"Hippocampal formation",question:"Which structure of the hippocampal formation is described as mainly afferent?",options:{A:"Subiculum",B:"Mammillary body",C:"Hippocampus proper",D:"Dentate gyrus"},correct:"D",explanation:"The dentate gyrus is described as the afferent part of the hippocampal formation."},
      {id:"cns-093",difficulty:"Hard",topic:"Limbic system",subtopic:"Fornix",question:"Which connection is made by the fornix?",options:{A:"Hippocampus with septal area and mammillary bodies",B:"Broca area with Wernicke area",C:"Cochlear nuclei with inferior colliculus",D:"Visual cortex with lateral geniculate body"},correct:"A",explanation:"The fornix connects the hippocampus with the septal area and mammillary bodies."},
      {id:"cns-094",difficulty:"Hard",topic:"Limbic system",subtopic:"Papez circuit",question:"Which sequence best represents the Papez circuit described in the notes?",options:{A:"Amygdala → stria terminalis → hypothalamus → anterior thalamic nuclei → cingulate cortex → amygdala",B:"Hippocampus → mammillary bodies → anterior thalamic nuclei → cingulate gyrus → entorhinal cortex → hippocampus",C:"Subiculum → fornix → septal nuclei → anterior commissure → parahippocampal gyrus → subiculum",D:"Olfactory bulb → piriform cortex → entorhinal cortex → dentate gyrus → CA3 → CA1 → subiculum"},correct:"B",explanation:"The Papez circuit links hippocampus, mammillary bodies, anterior thalamic nuclei, cingulate gyrus, entorhinal cortex, and back to hippocampus."},
      {id:"cns-095",difficulty:"Hard",topic:"Limbic system",subtopic:"Amygdala pathways",question:"Which white matter pathways connect the amygdala with hypothalamic and septal regions?",options:{A:"Optic radiation and acoustic radiation",B:"Corticospinal and corticobulbar tracts",C:"Stria terminalis and ventral amygdalofugal pathway",D:"Anterior and posterior spinocerebellar tracts"},correct:"C",explanation:"The stria terminalis and ventral amygdalofugal pathway connect the amygdala with septal, hypothalamic, and related limbic regions."},
      {id:"cns-096",difficulty:"Medium",topic:"Neurotransmitters",subtopic:"Classification",question:"Which neurotransmitter is described as the main excitatory neurotransmitter in the CNS?",options:{A:"GABA",B:"Serotonin",C:"Glycine",D:"Glutamate"},correct:"D",explanation:"Glutamate is the main excitatory neurotransmitter in the CNS."},
      {id:"cns-097",difficulty:"Medium",topic:"Neurotransmitters",subtopic:"GABA",question:"Which statement about GABA is correct?",options:{A:"It is inhibitory within the CNS and is involved in basal ganglia circuitry.",B:"It is produced by the pineal gland and controls circadian rhythm.",C:"It is the main excitatory neurotransmitter released by the subthalamic nucleus.",D:"It is found only at the neuromuscular junction."},correct:"A",explanation:"GABA is the main inhibitory neurotransmitter in the CNS and is important in basal ganglia circuits."},
      {id:"cns-098",difficulty:"Medium",topic:"Neurotransmitters",subtopic:"Serotonin",question:"Serotonin is primarily produced in which nuclei according to the notes?",options:{A:"Dentate nuclei",B:"Raphe nuclei",C:"Subthalamic nuclei",D:"Anterior thalamic nuclei"},correct:"B",explanation:"Serotonin is primarily produced in the raphe nuclei of the reticular formation."},
      {id:"cns-099",difficulty:"Hard",topic:"Spinal nerve",subtopic:"Dorsal root ganglion",question:"Which statement best describes dorsal root ganglion neurons?",options:{A:"They are multipolar motor neurons located in the anterior horn.",B:"They are glial cells that form the blood-brain barrier.",C:"They are pseudounipolar sensory neurons conveying information from receptors to the spinal cord.",D:"They are inhibitory interneurons located only in the cerebellar cortex."},correct:"C",explanation:"Dorsal root ganglia contain pseudounipolar sensory neurons that transmit sensory information from peripheral receptors into the spinal cord."},
      {id:"cns-100",difficulty:"Hard",topic:"Integrated CNS anatomy",subtopic:"Clinical localization",question:"A lesion causes loss of pain and temperature sensation on the contralateral side of the body, while dorsal column modalities below the lesion are preserved. Which tract is most likely affected?",options:{A:"Fasciculus gracilis",B:"Posterior spinocerebellar tract",C:"Corticobulbar tract",D:"Lateral spinothalamic tract"},correct:"D",explanation:"The lateral spinothalamic tract carries pain and temperature. Because these fibers decussate in the spinal cord, lesions typically cause contralateral pain and temperature loss."},
    ]},
    {name:"Lymphatic System",questions:[
      {id:"lym-001",difficulty:"Medium",topic:"Lymphoid organs",subtopic:"Primary and secondary lymphoid organs",question:"Which statement correctly distinguishes primary from secondary lymphoid organs?",options:{A:"Primary organs are where lymphocytes originate and differentiate; secondary organs are where antigen-driven immune responses occur.",B:"Primary lymphoid organs include tonsils and Peyer's patches, while secondary lymphoid organs include bone marrow only.",C:"Primary lymphoid organs only filter lymph, while secondary lymphoid organs produce erythrocytes.",D:"Primary and secondary lymphoid organs are identical terms for the same structures."},correct:"A",explanation:"Primary lymphoid organs include thymus and bone marrow, where lymphocytes originate or differentiate. Secondary lymphoid organs include lymph nodes, tonsils, Peyer's patches and spleen, where immune responses occur."},
      {id:"lym-002",difficulty:"Hard",topic:"Thymus",subtopic:"Embryological origin",question:"The thymus is derived embryologically from which structure according to the notes?",options:{A:"First pharyngeal arch",B:"Third pharyngeal arch",C:"Second pharyngeal pouch only",D:"Neural crest-derived paraxial mesoderm"},correct:"B",explanation:"The notes describe the thymus as a primary lymphoid organ derived from the third pharyngeal arch."},
      {id:"lym-003",difficulty:"Medium",topic:"Thymus",subtopic:"Position and syntopy",question:"Where is the thymus primarily located?",options:{A:"Posterior abdominal wall, anterior to the kidneys",B:"Right upper quadrant of the abdomen, beneath the liver",C:"Superior mediastinum, posterior to the manubrium of the sternum",D:"Within the inguinal canal, deep to the superficial inguinal lymph nodes"},correct:"C",explanation:"The thymus is an asymmetrical flat organ located mainly in the superior mediastinum behind the manubrium, with possible extension into the neck and anterior mediastinum."},
      {id:"lym-004",difficulty:"Hard",topic:"Thymus",subtopic:"Histological organization",question:"Which feature is characteristic of the thymic medulla?",options:{A:"Dense B-lymphocyte nodules with germinal centers and follicular dendritic cells",B:"Venous sinusoids lined by stave cells supporting red pulp blood filtration",C:"Lacteals absorbing dietary fat surrounded by enterocytes of the intestinal mucosa",D:"Fewer lymphocytes, more reticular epithelial cells, and Hassall's corpuscles"},correct:"D",explanation:"The thymic medulla contains fewer lymphocytes than the cortex, more reticular epithelial cells, and Hassall's corpuscles made of concentrically arranged epithelial reticular cells filled with keratin."},
      {id:"lym-005",difficulty:"Hard",topic:"Thymus",subtopic:"Function",question:"Which function best describes the thymus?",options:{A:"T-lymphocyte differentiation and removal of T cells reactive against self-antigens",B:"Filtration of old erythrocytes from blood through open splenic circulation",C:"Absorption of digested fats from the intestinal lumen into lacteals",D:"Drainage of the right upper limb directly into the cisterna chyli"},correct:"A",explanation:"The thymus is the site of T-lymphocyte differentiation and thymic selection, where self-reactive T lymphocytes are removed."},
      {id:"lym-006",difficulty:"Medium",topic:"Thymus",subtopic:"Age-related changes",question:"What happens to the thymus after puberty?",options:{A:"It becomes the main site of erythrocyte destruction.",B:"It atrophies and is progressively replaced by adipose tissue.",C:"It transforms into the spleen.",D:"It begins producing bile and pancreatic enzymes."},correct:"B",explanation:"The thymus is highly active at birth and during early childhood, but after puberty its activity decreases and it undergoes fatty replacement."},
      {id:"lym-007",difficulty:"Hard",topic:"Thymus",subtopic:"Vasculature",question:"Which set of arteries contributes to the arterial supply of the thymus according to the PDF?",options:{A:"Splenic artery and short gastric arteries arising from the celiac trunk",B:"Superior mesenteric artery and inferior mesenteric artery from the abdominal aorta",C:"Anterior intercostal arteries, superior/inferior thyroid branches, and internal thoracic artery branches",D:"Testicular arteries and lumbar arteries from the abdominal aorta only"},correct:"C",explanation:"The thymus receives arterial supply from anterior intercostal arteries and small branches from the superior thyroid, inferior thyroid and internal thoracic arteries."},
      {id:"lym-008",difficulty:"Medium",topic:"Lymph node",subtopic:"General function",question:"What is the main function of lymph nodes?",options:{A:"To produce bile and store glycogen",B:"To destroy old erythrocytes through splenic cords",C:"To oxygenate lymph before it enters the bloodstream",D:"To filter lymph and support immune responses against detected antigens"},correct:"D",explanation:"Lymph nodes filter lymph before it re-enters the bloodstream and contain immune cells such as T cells, B cells, macrophages and APCs."},
      {id:"lym-009",difficulty:"Hard",topic:"Lymph node",subtopic:"Cortex",question:"Which lymph node region contains lymphoid nodules formed mainly by B-lymphocytes?",options:{A:"Cortex",B:"Paracortex",C:"Medullary sinus only",D:"Hilum only"},correct:"A",explanation:"The cortex lies beneath the capsule and contains lymphoid nodules composed mainly of B-lymphocytes."},
      {id:"lym-010",difficulty:"Hard",topic:"Lymph node",subtopic:"Paracortex",question:"The paracortex of a lymph node is mainly characterized by which feature?",options:{A:"It is the main site of old red blood cell destruction.",B:"It contains T-lymphocytes and high endothelial venules.",C:"It contains Hassall's corpuscles arranged concentrically.",D:"It is the primary site of fat absorption from the gut lumen."},correct:"B",explanation:"The paracortex lacks B-cell nodules and is rich in T-lymphocytes. It also contains high endothelial venules that allow rapid lymphocyte entry."},
      {id:"lym-011",difficulty:"Hard",topic:"Lymph node",subtopic:"Medulla",question:"Which statement correctly describes the medulla of a lymph node?",options:{A:"It contains only epithelial reticular cells and no lymphocytes.",B:"It is the first sinus entered directly from afferent lymphatic vessels.",C:"It contains medullary cords with B-lymphocytes and macrophages, separated by sinuses carrying lymph.",D:"It is located outside the capsule and drains into the thoracic duct directly."},correct:"C",explanation:"The medulla contains medullary cords with B-lymphocytes and macrophages, separated by medullary sinuses that contain lymph and macrophages."},
      {id:"lym-012",difficulty:"Hard",topic:"Lymph node",subtopic:"Lymph flow",question:"Which sequence correctly describes lymph flow through a lymph node?",options:{A:"Efferent lymph vessel → medullary sinus → cortical sinus → subcapsular sinus → afferent lymph vessel",B:"Medullary cord → Hassall's corpuscle → paracortex → splenic sinus",C:"Afferent lymph vessel → hilum → thoracic duct → subcapsular sinus",D:"Afferent lymph vessel → subcapsular sinus → cortical sinus → medullary sinus → efferent lymph vessel"},correct:"D",explanation:"Lymph enters via afferent lymphatic vessels, passes through subcapsular, cortical and medullary sinuses, and exits via an efferent lymphatic vessel at the hilum."},
      {id:"lym-013",difficulty:"Medium",topic:"Sentinel lymph node",subtopic:"Clinical relevance",question:"What is a sentinel lymph node?",options:{A:"The first lymph node that drains lymph from a particular organ or region",B:"A thymic corpuscle involved in T-cell selection",C:"A splenic lymphoid nodule surrounding a central arteriole",D:"The largest lymph node in the body"},correct:"A",explanation:"A sentinel lymph node is the first node draining an organ or region, making it clinically important in the spread of malignancy."},
      {id:"lym-014",difficulty:"Hard",topic:"Main lymphatic ducts",subtopic:"Thoracic duct",question:"Which drainage territory belongs to the thoracic duct?",options:{A:"Only the right upper limb and right side of the head",B:"Lower body, left upper limb, and left head and neck",C:"Only the thoracic wall and right lung",D:"Only the thymus and spleen"},correct:"B",explanation:"The thoracic duct drains the whole lower body, left upper limb, and left head and neck into the left venous angle."},
      {id:"lym-015",difficulty:"Medium",topic:"Main lymphatic ducts",subtopic:"Right lymphatic duct",question:"The right lymphatic duct drains mainly into which site?",options:{A:"Cisterna chyli",B:"Portal vein",C:"Right venous angle",D:"Left venous angle"},correct:"C",explanation:"The right lymphatic duct drains lymph from the right upper quadrant of the body into the right venous angle."},
      {id:"lym-016",difficulty:"Hard",topic:"MALT",subtopic:"Mucosa-associated lymphoid tissue",question:"Which statement best describes MALT?",options:{A:"Encapsulated lymphoid tissue with a fibrous capsule found only in the spleen",B:"A concentrically arranged epithelial corpuscle characteristic of the thymic medulla",C:"A lymphatic collecting duct that drains the right upper quadrant into the right venous angle",D:"Non-encapsulated lymphoid tissue found in mucosal linings exposed to the external environment"},correct:"D",explanation:"MALT is non-encapsulated lymphoid tissue found in mucosal organs of the digestive, respiratory and genitourinary tracts, which are exposed to pathogens from the external environment."},
      {id:"lym-017",difficulty:"Medium",topic:"Spleen",subtopic:"Organ classification",question:"Which statement correctly describes the spleen?",options:{A:"It is a secondary lymphoid organ located in the upper left abdomen.",B:"It is a primary lymphoid organ located in the superior mediastinum.",C:"It is a non-encapsulated MALT structure located in the ileum.",D:"It is a lymphatic duct arising from the cisterna chyli."},correct:"A",explanation:"The spleen is a secondary lymphoid organ located in the upper left quadrant of the abdomen, under the diaphragm and ribcage."},
      {id:"lym-018",difficulty:"Hard",topic:"Spleen",subtopic:"Peritoneal relations",question:"Which ligaments connect the spleen to nearby organs?",options:{A:"Falciform ligament to the liver and hepatoduodenal ligament to the duodenum",B:"Gastrosplenic ligament to the stomach and splenorenal ligament to the kidney",C:"Broad ligament to the uterus and suspensory ligament to the ovary",D:"Median umbilical ligament to the bladder and mesoappendix to the appendix"},correct:"B",explanation:"The spleen is attached to the stomach by the gastrosplenic ligament and to the kidney by the splenorenal ligament."},
      {id:"lym-019",difficulty:"Hard",topic:"Spleen",subtopic:"White and red pulp",question:"Which statement correctly distinguishes white pulp from red pulp?",options:{A:"White pulp contains only erythrocytes, while red pulp contains only lymphocytes.",B:"White pulp is adipose tissue, while red pulp is bone marrow.",C:"White pulp is lymphoid tissue, while red pulp contains blood cells and participates in blood filtration.",D:"White pulp forms Hassall's corpuscles, while red pulp forms thymic cortex."},correct:"C",explanation:"The spleen contains white pulp rich in lymphoid tissue and red pulp filled with blood cells, venous sinusoids and splenic cords."},
      {id:"lym-020",difficulty:"Hard",topic:"Spleen",subtopic:"Red pulp function",question:"In open splenic circulation, why are old erythrocytes removed?",options:{A:"They are actively pumped into the thymus for selection.",B:"They are filtered only by high endothelial venules in the lymph node paracortex.",C:"They enter lacteals and are digested by pancreatic enzymes.",D:"Aged erythrocytes lose membrane flexibility and are phagocytosed by macrophages in splenic cords."},correct:"D",explanation:"Old erythrocytes lose membrane flexibility and cannot pass between stave cells lining venous sinusoids, so they are engulfed by macrophages in splenic cords."},
      {id:"lym-021",difficulty:"Medium",topic:"Spleen",subtopic:"Blood supply",question:"What is the main arterial supply of the spleen?",options:{A:"Splenic artery from the celiac trunk",B:"Inferior mesenteric artery",C:"Superior mesenteric artery",D:"Internal iliac artery"},correct:"A",explanation:"The spleen is supplied by the splenic artery, a branch of the celiac trunk."},
      {id:"lym-022",difficulty:"Hard",topic:"Spleen",subtopic:"Segmental blood supply",question:"Why can specific sections of the spleen be surgically removed more easily?",options:{A:"Because the spleen has no capsule.",B:"Because splenic arterial branches form non-anastomosing vascular segments.",C:"Because the spleen has only venous drainage and no arterial supply.",D:"Because the spleen is supplied directly by the right lymphatic duct."},correct:"B",explanation:"Splenic arterial branches do not anastomose significantly, creating vascular segments that allow segmental splenectomy."},
      {id:"lym-023",difficulty:"Medium",topic:"Spleen",subtopic:"Venous drainage",question:"The splenic vein combines with which vessel to form the portal vein?",options:{A:"Inferior vena cava",B:"Left renal vein",C:"Superior mesenteric vein",D:"Internal iliac vein"},correct:"C",explanation:"The splenic vein joins the superior mesenteric vein to form the portal vein."},
      {id:"lym-024",difficulty:"Hard",topic:"Spleen",subtopic:"Histological blood flow",question:"Which sequence correctly describes splenic arterial blood flow into the pulp?",options:{A:"Splenic artery → high endothelial venules → paracortex → efferent lymphatic",B:"Splenic artery → lacteals → celiac lymph nodes → cisterna chyli",C:"Splenic artery → subcapsular sinus → cortical sinus → medullary sinus",D:"Splenic artery → trabecular arteries → central arterioles surrounded by PALS → penicillar arterioles"},correct:"D",explanation:"Splenic artery branches enter as trabecular arteries, leave trabeculae as central arterioles surrounded by periarteriolar lymphoid sheath, then give rise to penicillar arterioles."},
      {id:"lym-025",difficulty:"Hard",topic:"Head and neck lymphatics",subtopic:"Superficial and deep vessels",question:"Which statement correctly describes lymphatic vessels of the head and neck?",options:{A:"Superficial vessels drain the scalp, face, and neck into a ring of nodes at the head-neck junction.",B:"Deep lymphatics drain directly into the popliteal nodes.",C:"The right jugular trunk always empties directly into the thoracic duct.",D:"The left jugular trunk drains into the right venous angle."},correct:"A",explanation:"Superficial vessels drain the scalp, face and neck into superficial lymph nodes at the junction of the head and neck. Deep vessels converge into jugular lymphatic trunks."},
      {id:"lym-026",difficulty:"Hard",topic:"Head and neck lymph nodes",subtopic:"Occipital and mastoid nodes",question:"Which lymph nodes collect lymph from the occipital area of the scalp?",options:{A:"Submental lymph nodes",B:"Occipital lymph nodes",C:"Parotid lymph nodes",D:"Pretracheal lymph nodes"},correct:"B",explanation:"Occipital lymph nodes are located at the back of the head near the lateral border of trapezius and collect lymph from the occipital scalp."},
      {id:"lym-027",difficulty:"Medium",topic:"Head and neck lymph nodes",subtopic:"Submental nodes",question:"The submental lymph nodes drain which region?",options:{A:"External acoustic meatus and nasal cavity only",B:"Posterior scalp and upper ear",C:"Lower lip, floor of the oral cavity, and apex of the tongue",D:"Deep thoracic wall and diaphragm"},correct:"C",explanation:"Submental lymph nodes lie superficial to the mylohyoid muscle and drain the lower lip, floor of the oral cavity and apex of the tongue."},
      {id:"lym-028",difficulty:"Medium",topic:"Head and neck lymph nodes",subtopic:"Submandibular nodes",question:"Which lymph nodes are located below the mandible in the submandibular triangle and receive lymph from cheeks, lateral nose, upper lip and also from submental/facial nodes?",options:{A:"Occipital nodes",B:"Supraclavicular nodes",C:"Mastoid nodes",D:"Submandibular nodes"},correct:"D",explanation:"Submandibular lymph nodes are located below the mandible and drain the cheeks, lateral nose and upper lip, also receiving lymph from submental and facial nodes."},
      {id:"lym-029",difficulty:"Hard",topic:"Deep cervical lymph nodes",subtopic:"Drainage",question:"Which statement about deep cervical lymph nodes is correct?",options:{A:"They drain all head and neck lymph and run vertically along the jugular vein.",B:"They are located only in the popliteal fossa.",C:"They drain directly into the intestinal lymphatic trunk.",D:"They are found only inside the thymic medulla."},correct:"A",explanation:"Deep cervical nodes receive all lymph from the head and neck and are organized vertically close to the internal jugular vein; their efferents form the jugular lymphatic trunks."},
      {id:"lym-030",difficulty:"Hard",topic:"Thoracic wall lymphatics",subtopic:"Deep drainage",question:"Which deep lymph node group of the thoracic wall drains into the bronchomediastinal trunk?",options:{A:"Popliteal lymph nodes",B:"Parasternal lymph nodes",C:"Celiac lymph nodes",D:"Lumbar lymph nodes"},correct:"B",explanation:"Parasternal lymph nodes drain into the bronchomediastinal trunk. Phrenic nodes drain into parasternal nodes."},
      {id:"lym-031",difficulty:"Hard",topic:"Breast lymph drainage",subtopic:"Axillary drainage",question:"Approximately 75% of lymph from the breast drains first mainly to which lymph nodes?",options:{A:"Celiac lymph nodes, then cisterna chyli",B:"Popliteal lymph nodes, then inguinal lymph nodes",C:"Pectoral lymph nodes, then axillary lymph nodes",D:"Lumbar lymph nodes, then thoracic duct"},correct:"C",explanation:"About 75% of breast lymph drains into pectoral lymph nodes and then axillary lymph nodes."},
      {id:"lym-032",difficulty:"Hard",topic:"Breast lymph drainage",subtopic:"Parasternal drainage",question:"The remaining 25% of breast lymph mainly drains into which lymph nodes?",options:{A:"Deep cervical lymph nodes",B:"Occipital lymph nodes",C:"Superior mesenteric lymph nodes",D:"Parasternal lymph nodes"},correct:"D",explanation:"The remaining 25% of breast lymph drains into parasternal lymph nodes, which drain into bronchomediastinal trunks."},
      {id:"lym-033",difficulty:"Hard",topic:"Thoracic duct",subtopic:"Course",question:"Which statement correctly describes the thoracic duct course?",options:{A:"It originates from the cisterna chyli at L1/L2 and drains into the left venous angle.",B:"It begins at the thymus and terminates in the portal vein.",C:"It begins in the right venous angle and descends into the pelvis.",D:"It begins in the spleen and drains directly into the superior mesenteric vein."},correct:"A",explanation:"The thoracic duct arises from the cisterna chyli at L1/L2, enters the thorax via the aortic hiatus at T12, ascends, crosses left at T4-T6, and drains into the left venous angle."},
      {id:"lym-034",difficulty:"Hard",topic:"Lung lymph drainage",subtopic:"Superficial and deep plexuses",question:"Which statement correctly describes lung lymphatic drainage?",options:{A:"Both plexuses drain to the inguinal nodes then up to the external and common iliac nodes.",B:"Superficial plexus drains visceral pleura to bronchopulmonary nodes; deep plexus drains bronchial wall to pulmonary nodes.",C:"The superficial plexus drains the pancreas and liver to celiac nodes via the intestinal trunk.",D:"The deep plexus drains directly into the portal vein via the hepatic sinusoids."},correct:"B",explanation:"The superficial plexus of the lungs and visceral pleura drains into bronchopulmonary nodes. The deep plexus in bronchial submucosa drains the lung root into pulmonary nodes, then bronchopulmonary and tracheobronchial nodes."},
      {id:"lym-035",difficulty:"Medium",topic:"Abdominal lymph nodes",subtopic:"Pre-aortic nodes",question:"Which lymph node groups are classified as pre-aortic lymph nodes?",options:{A:"Popliteal, superficial inguinal, and deep inguinal nodes",B:"Occipital, mastoid, and preauricular nodes",C:"Celiac, superior mesenteric, and inferior mesenteric lymph nodes",D:"Anterior, central, and apical axillary nodes"},correct:"C",explanation:"Pre-aortic lymph nodes lie in front of the aorta and are grouped into celiac, superior mesenteric and inferior mesenteric lymph nodes."},
      {id:"lym-036",difficulty:"Hard",topic:"Stomach lymph drainage",subtopic:"Celiac pathway",question:"Which pathway correctly describes stomach lymph drainage?",options:{A:"Stomach lymphatics → deep cervical nodes → jugular trunk",B:"Stomach lymphatics → popliteal lymph nodes → lumbar trunk → right venous angle",C:"Stomach lymphatics → superficial inguinal nodes → external iliac nodes only",D:"Stomach lymphatics → gastric and gastro-omental nodes → celiac nodes → intestinal trunk → cisterna chyli"},correct:"D",explanation:"Stomach lymph vessels travel along the curvatures to gastric and gastro-omental nodes, then celiac nodes, then the intestinal trunk, and finally the cisterna chyli."},
      {id:"lym-037",difficulty:"Hard",topic:"Liver lymph drainage",subtopic:"Superficial lymphatics",question:"The superficial lymphatics from the anterior aspect of the liver capsule drain first mainly into which nodes?",options:{A:"Hepatic lymph nodes at the porta hepatis",B:"Popliteal lymph nodes draining the posterior knee",C:"Submental lymph nodes beneath the chin",D:"Apical axillary lymph nodes of the axillary chain"},correct:"A",explanation:"Superficial lymphatics from the anterior liver capsule drain to hepatic lymph nodes at the porta hepatis, then to celiac nodes and the cisterna chyli."},
      {id:"lym-038",difficulty:"Hard",topic:"Pancreas lymph drainage",subtopic:"Regional drainage",question:"Which statement about pancreatic lymph drainage is correct?",options:{A:"The pancreas drains only to superficial inguinal lymph nodes.",B:"The head drains to pancreaticoduodenal nodes; the tail drains to splenic nodes near the splenic artery.",C:"The tail drains directly into the right lymphatic duct without lymph nodes.",D:"The pancreatic body drains into occipital nodes."},correct:"B",explanation:"The pancreatic head drains to pancreaticoduodenal nodes, while the tail drains to splenic nodes along the splenic artery; these pathways ultimately reach celiac nodes and cisterna chyli."},
      {id:"lym-039",difficulty:"Hard",topic:"Small intestine lymph drainage",subtopic:"Lacteals and mesenteric nodes",question:"Which sequence best describes lymph drainage from most of the small intestine?",options:{A:"Lacteals → popliteal nodes → superficial inguinal nodes → external iliac nodes",B:"Lacteals → submental nodes → jugular trunk → right venous angle",C:"Lacteals → juxta-intestinal nodes → superior mesenteric nodes → celiac nodes → cisterna chyli",D:"Lacteals → pulmonary nodes → tracheobronchial nodes → bronchomediastinal trunk"},correct:"C",explanation:"Small intestinal lacteals drain into mesenteric lymph nodes, including juxta-intestinal and intermediate nodes, then superior mesenteric nodes, celiac nodes and cisterna chyli."},
      {id:"lym-040",difficulty:"Hard",topic:"Large intestine lymph drainage",subtopic:"Colon segments",question:"Which large intestine lymph drainage pairing is correct?",options:{A:"Ascending colon → left colic nodes → inferior mesenteric lymph nodes",B:"Transverse colon → right colic nodes → superior mesenteric lymph nodes",C:"Appendix → middle colic nodes → superior mesenteric lymph nodes",D:"Descending colon → left colic lymph nodes → inferior mesenteric lymph nodes"},correct:"D",explanation:"The descending colon drains to left colic lymph nodes, then to inferior mesenteric lymph nodes and onward to cisterna chyli via the intestinal lymphatic trunk. The ascending colon drains to right colic (not left colic) nodes then superior mesenteric nodes. The transverse colon drains to middle colic (not right colic) nodes. The appendix drains to ileocolic (not middle colic) nodes."},
      {id:"lym-041",difficulty:"Hard",topic:"Rectum and anal canal",subtopic:"Segmental drainage",question:"Which statement about anal canal lymph drainage is correct?",options:{A:"Above the pectinate line drains to internal iliac nodes; below drains to inguinal nodes.",B:"Above and below the pectinate line both drain only to celiac nodes.",C:"Below the pectinate line drains directly to deep cervical nodes.",D:"The anal canal has no lymphatic drainage."},correct:"A",explanation:"Above the pectinate line, lymph drains to internal iliac nodes. Below the pectinate line, lymph drains to superficial inguinal nodes."},
      {id:"lym-042",difficulty:"Hard",topic:"Male reproductive lymph drainage",subtopic:"Testis and epididymis",question:"Where do the testis and epididymis primarily drain lymph?",options:{A:"Superficial inguinal lymph nodes, reflecting the scrotal embryological origin",B:"Right or left lumbar lymph nodes, then para-aortic/lumbar trunks toward cisterna chyli",C:"Deep cervical lymph nodes along the internal jugular vein",D:"Pectoral lymph nodes of the axillary group"},correct:"B",explanation:"The right and left testes and epididymides drain to the corresponding lumbar lymph nodes, then to para-aortic nodes/lumbar trunks and cisterna chyli."},
      {id:"lym-043",difficulty:"Hard",topic:"Male reproductive lymph drainage",subtopic:"Scrotum and penis",question:"Which statement about external male genital lymph drainage is correct?",options:{A:"The glans penis drains directly to the thoracic duct without nodes.",B:"The skin of the penis drains only to celiac nodes.",C:"The scrotum drains mainly to superficial inguinal lymph nodes.",D:"The testes and scrotum have identical primary lymph drainage."},correct:"C",explanation:"The scrotum drains to superficial inguinal nodes. This differs from the testes, which drain to lumbar nodes because of their embryological origin."},
      {id:"lym-044",difficulty:"Hard",topic:"Female reproductive lymph drainage",subtopic:"Vagina",question:"Which vaginal lymph drainage pattern is correct?",options:{A:"Inferior segment drains directly into the cisterna chyli.",B:"All segments drain only to lumbar lymph nodes.",C:"Superior segment drains to popliteal nodes; middle segment drains to axillary nodes.",D:"Superior vagina → external iliac nodes; middle vagina → internal iliac nodes; inferior vagina → inguinal nodes"},correct:"D",explanation:"The superior vagina drains to external iliac nodes, the middle vagina to internal iliac nodes, and the inferior vagina/external orifice to superficial inguinal nodes."},
      {id:"lym-045",difficulty:"Hard",topic:"Female reproductive lymph drainage",subtopic:"Uterus",question:"Which uterine lymph drainage pairing is correct?",options:{A:"Fundus → superficial inguinal lymph nodes",B:"Cervix → occipital nodes",C:"Body → popliteal lymph nodes",D:"Fundus → bronchopulmonary lymph nodes"},correct:"A",explanation:"The uterine fundus drains to superficial inguinal nodes, the body to external iliac nodes, and the cervix to internal iliac nodes."},
      {id:"lym-046",difficulty:"Medium",topic:"Female reproductive lymph drainage",subtopic:"Ovaries and tubes",question:"Where do the ovaries primarily drain lymph?",options:{A:"Superficial cervical lymph nodes",B:"Right or left lumbar lymph nodes",C:"Parotid lymph nodes",D:"Pectoral lymph nodes"},correct:"B",explanation:"The ovaries drain to the right or left lumbar lymph nodes. The fallopian tubes drain to lumbar and internal iliac nodes."},
      {id:"lym-047",difficulty:"Hard",topic:"Upper limb lymphatics",subtopic:"Superficial vessels",question:"Which statement correctly describes superficial lymphatic drainage of the upper limb?",options:{A:"Superficial vessels of the upper limb drain first to popliteal nodes and then to inguinal nodes.",B:"All superficial vessels from the upper limb enter directly into the cisterna chyli without nodes.",C:"Basilic-side vessels enter cubital then humeral nodes; cephalic-side vessels enter apical axillary or deltopectoral nodes.",D:"Superficial lymphatics of the upper limb travel independently without following the course of veins."},correct:"C",explanation:"Superficial upper limb lymphatics travel with superficial veins: basilic-associated vessels enter cubital then humeral nodes, while cephalic-associated vessels enter apical axillary or deltopectoral nodes."},
      {id:"lym-048",difficulty:"Hard",topic:"Axillary lymph nodes",subtopic:"Groups",question:"Which axillary lymph node group receives most lymph from the upper limb?",options:{A:"Pectoral nodes",B:"Subscapular nodes",C:"Parasternal nodes",D:"Humeral/lateral nodes"},correct:"D",explanation:"The humeral, or lateral, axillary lymph nodes receive most lymph drained from the upper limb."},
      {id:"lym-049",difficulty:"Hard",topic:"Axillary lymph nodes",subtopic:"Efferent drainage",question:"Which pathway correctly describes efferent lymph drainage from the apical axillary nodes?",options:{A:"Apical nodes → cervico-axillary canal → subclavian lymphatic trunk",B:"Apical nodes → thoracic duct → popliteal nodes → lumbar trunks",C:"Apical nodes → parasternal nodes → celiac nodes → intestinal trunk",D:"Apical nodes → bronchomediastinal trunk → splenic vein → portal vein"},correct:"A",explanation:"Efferent vessels from the apical axillary nodes pass through the cervico-axillary canal and converge to form the subclavian lymphatic trunk."},
      {id:"lym-050",difficulty:"Hard",topic:"Lower limb lymphatics",subtopic:"Superficial and deep vessels",question:"Which statement correctly describes lymphatic drainage of the lower limb?",options:{A:"All lower limb lymph drains first to axillary apical nodes.",B:"Medial vessels follow the great saphenous to sub-inguinal nodes; lateral vessels follow the small saphenous to popliteal nodes.",C:"Deep lymphatic vessels of the lower limb follow superficial veins only and avoid popliteal nodes.",D:"The lower limb drains directly into the right lymphatic duct without lymph nodes."},correct:"B",explanation:"Medial superficial vessels from the dorsum of the foot ascend with the great saphenous vein to sub-inguinal nodes. Lateral vessels ascend with the small saphenous vein and drain to popliteal nodes or join the medial group."},
    ]},
  ];
})();